function findTemplate(topic: string): Template | null {
  const lower = topic.toLowerCase().trim();
  for (const t of TEMPLATES) {
    if (lower.includes(t.topic) || t.topic.includes(lower)) return t;
  }
  // partial match
  for (const t of TEMPLATES) {
    const words = t.topic.split(/\s+/);
    for (const w of words) {
      if (lower.includes(w) && w.length > 3) return t;
    }
  }
  return null;
}

function generateParagraph(topic: string, tone: Tone, length: Length): string {
  const match = findTemplate(topic);
  if (match) return match[tone][length];

  // Generic fallback
  const toneIntros: Record<Tone, string> = {
    formal: `${topic.charAt(0).toUpperCase() + topic.slice(1)} is a subject of considerable importance in contemporary discourse.`,
    casual: `So, let's talk about ${topic} — it's something a lot of people are curious about these days.`,
    persuasive: `If you haven't been paying attention to ${topic}, now is the time to start, because it matters more than ever.`,
    academic: `The study of ${topic} has attracted growing scholarly attention across multiple disciplines in recent years.`,
  };

  const toneBodies: Record<Tone, string> = {
    formal: `Understanding the various dimensions of ${topic} requires careful analysis and consideration of multiple perspectives. Experts in the field emphasize the importance of evidence-based approaches and systematic evaluation when addressing this subject. The implications extend across professional, social, and personal domains, making informed engagement essential for stakeholders at every level.`,
    casual: `It's one of those topics that seems to come up everywhere, from conversations with friends to stuff you see online. There's a lot to learn about it, and honestly, the more you dig in, the more interesting it gets. Everyone has their own take on it, which makes discussions about ${topic} pretty lively and fun.`,
    persuasive: `The evidence supporting the significance of ${topic} is overwhelming and impossible to ignore. Those who take the time to understand it gain a meaningful advantage, whether in their personal lives, professional endeavors, or broader worldview. Failing to engage with ${topic} is not neutrality; it is a missed opportunity with real consequences.`,
    academic: `Current literature reveals a multifaceted phenomenon that resists simplistic characterization, requiring interdisciplinary methodologies for comprehensive analysis. Theoretical frameworks drawn from diverse fields provide complementary lenses through which to examine the complexities of ${topic}. Empirical research continues to expand our understanding, though significant questions remain for future investigation.`,
  };

  const toneClosings: Record<Tone, string> = {
    formal: `Continued attention to ${topic} will be essential as its relevance to society and individuals alike continues to grow.`,
    casual: `At the end of the day, ${topic} is worth knowing about, and you might be surprised how much it connects to your everyday life.`,
    persuasive: `The time to engage with ${topic} is now — those who act will lead, and those who wait will follow.`,
    academic: `Further research is warranted to deepen our understanding of ${topic} and its broader implications for theory and practice.`,
  };

  if (length === "short") {
    return `${toneIntros[tone]} ${toneClosings[tone]}`;
  } else if (length === "medium") {
    return `${toneIntros[tone]} ${toneBodies[tone]} ${toneClosings[tone]}`;
  } else {
    return `${toneIntros[tone]} ${toneBodies[tone]} This is particularly relevant given the rapid changes occurring in our world today. As new information emerges and perspectives evolve, staying informed about ${topic} becomes not just beneficial but necessary for anyone who wishes to participate meaningfully in related conversations and decisions. ${toneClosings[tone]}`;
  }
}

export default function ParagraphWriterPage() {
  const [topic, setTopic] = useState("");
  const [tone, setTone] = useState<Tone>("formal");
  const [length, setLength] = useState<Length>("medium");
  const [output, setOutput] = useState("");
  const [copied, setCopied] = useState(false);

  const handleGenerate = () => {
    if (!topic.trim()) return;
    const result = generateParagraph(topic.trim(), tone, length);
    setOutput(result);
    setCopied(false);
  };

  const handleCopy = () => {
    if (!output) return;
    navigator.clipboard.writeText(output).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  const wordCount = useMemo(() => {
    if (!output) return 0;
    return output.trim().split(/\s+/).filter(Boolean).length;
  }, [output]);

  return (
    <>
      
        <title>{META.title} | {SITE_NAME}</title>
        <meta name="description" content={META.description} />
        <meta name="keywords" content={META.keywords} />
        <link rel="canonical" href={`${SITE_URL}/tools/paragraph-writer`} />
        <meta property="og:title" content={META.title} />
        <meta property="og:description" content={META.description} />
        <meta property="og:type" content="website" />
        <meta property="og:url" content={`/tools/paragraph-writer`} />
        <meta name="twitter:card" content="summary" />
        <meta name="twitter:title" content={META.title} />
        <meta name="twitter:description" content={META.description} />
      

      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="mb-6">
          <a href="/" className="text-sm text-[var(--primary)] hover:underline">&larr; All Tools</a>
        </div>

        <h1 className="text-3xl font-extrabold mb-2">Paragraph Writer</h1>
        <p className="text-[var(--muted)] mb-8">
          Generate well-structured paragraphs on any topic with customizable tone and length.
        </p>

        <div className="ad-placeholder mb-8">Advertisement</div>

        <div className="tool-card mb-6">
          <label className="block text-sm font-semibold mb-2">Topic</label>
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            className="input-field"
            placeholder="e.g. technology, climate change, education, health..."
          />

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
            <div>
              <label className="block text-sm font-semibold mb-2">Tone</label>
              <select
                value={tone}
                onChange={(e) => setTone(e.target.value as Tone)}
                className="input-field"
              >
                {TONES.map((t) => (
                  <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-semibold mb-2">Length</label>
              <select
                value={length}
                onChange={(e) => setLength(e.target.value as Length)}
                className="input-field"
              >
                {LENGTHS.map((l) => (
                  <option key={l} value={l}>{l.charAt(0).toUpperCase() + l.slice(1)}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="flex gap-3 mt-4">
            <button onClick={handleGenerate} disabled={!topic.trim()} className="btn-primary">
              Generate Paragraph
            </button>
            {output && (
              <button onClick={() => { setOutput(""); setTopic(""); }} className="btn-secondary text-sm">
                Clear
              </button>
            )}
          </div>
        </div>

        {output && (
          <div className="result-card mb-6">
            <div className="flex justify-between items-center mb-3">
              <h3 className="font-semibold">Generated Paragraph</h3>
              <div className="flex items-center gap-3">
                <span className="text-xs text-[var(--muted)]">{wordCount} words</span>
                <button onClick={handleCopy} className="btn-secondary text-sm">
                  {copied ? "Copied!" : "Copy"}
                </button>
              </div>
            </div>
            <textarea
              value={output}
              onChange={(e) => setOutput(e.target.value)}
              className="input-field min-h-[180px] resize-y text-sm leading-relaxed"
            />
          </div>
        )}

        <div className="ad-placeholder mb-8">Advertisement</div>

        <div className="seo-content tool-card">
          <h2>What is a Paragraph Writer?</h2>
          <p>
            A Paragraph Writer generates well-structured paragraphs on any topic with customizable tone and length.
            Choose from formal, casual, persuasive, or academic tones and short, medium, or long paragraphs to match your needs.
          </p>

          <h2>How Does It Work?</h2>
          <ul>
            <li><strong>Topic Templates:</strong> Pre-written paragraphs for 15+ popular topics across all tones and lengths</li>
            <li><strong>Tone Control:</strong> Choose formal, casual, persuasive, or academic writing styles</li>
            <li><strong>Length Options:</strong> Generate short (2-3 sentences), medium (4-6 sentences), or long (7+ sentences) paragraphs</li>
            <li><strong>Editable Output:</strong> Modify the generated text directly in the output area</li>
          </ul>

          <h2>Who Uses Paragraph Writers?</h2>
          <ul>
            <li><strong>Students:</strong> Get started on essays and assignments with well-structured paragraphs</li>
            <li><strong>Writers:</strong> Overcome writer's block with topic-based paragraph templates</li>
            <li><strong>Professionals:</strong> Draft formal communications and reports efficiently</li>
            <li><strong>Content Creators:</strong> Generate blog post sections and social media content</li>
          </ul>
        </div>
      </div>

      <script
        type="application/ld+json"
        suppressHydrationWarning
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "WebApplication",
            name: "Paragraph Writer",
            description: META.description,
            url: `${SITE_URL}/tools/paragraph-writer`,
            applicationCategory: "UtilityApplication",
            operatingSystem: "Any",
            offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
          }),
        }}
      />
    </>
  );
}
